const neighbors=(a,b)=>Math.abs(a-b)===1;
const immediatelyRight=(a,b)=>b===a+1;
const checks={};
for(const h of HOUSES){
  checks['2a']=checks['2a']??true; if(nations[h]==='Englishman'&&colors[h]!=='Red')checks['2a']=false;
