  checks['3a']=checks['3a']??true; if(nations[h]==='Spaniard'&&pets[h]!=='Dog')checks['3a']=false;
  checks['3b']=checks['3b']??true; if(pets[h]==='Dog'&&nations[h]!=='Spaniard')checks['3b']=false;
  checks['4a']=checks['4a']??true; if(colors[h]==='Green'&&beverages[h]!=='Coffee')checks['4a']=false;
  checks['4b']=checks['4b']??true; if(beverages[h]==='Coffee'&&colors[h]!=='Green')checks['4b']=false;
  checks['5a']=checks['5a']??true; if(nations[h]==='Ukrainian'&&beverages[h]!=='Tea')checks['5a']=false;
  checks['5b']=checks['5b']??true; if(beverages[h]==='Tea'&&nations[h]!=='Ukrainian')checks['5b']=false;
  checks['7a']=checks['7a']??true; if(pets[h]==='Snail'&&hobbies[h]!=='Dancing')checks['7a']=false;
  checks['7b']=checks['7b']??true; if(hobbies[h]==='Dancing'&&pets[h]!=='Snail')checks['7b']=false;
  checks['8a']=checks['8a']??true; if(colors[h]==='Yellow'&&hobbies[h]!=='Painting')checks['8a']=false;
  checks['8b']=checks['8b']??true; if(hobbies[h]==='Painting'&&colors[h]!=='Yellow')checks['8b']=false;
  checks['13a']=checks['13a']??true; if(hobbies[h]==='Football'&&beverages[h]!=='Orange juice')checks['13a']=false;
  checks['13b']=checks['13b']??true; if(beverages[h]==='Orange juice'&&hobbies[h]!=='Football')checks['13b']=false;
  checks['14a']=checks['14a']??true; if(nations[h]==='Japanese'&&hobbies[h]!=='Chess')checks['14a']=false;
  checks['14b']=checks['14b']??true; if(hobbies[h]==='Chess'&&nations[h]!=='Japanese')checks['14b']=false;
}
const g=housesOf(colors,'Green'),iv=housesOf(colors,'Ivory');
checks['6']=!(g.length===1&&iv.length===1&&!immediatelyRight(iv[0],g[0]));
const r=housesOf(hobbies,'Reading'),f=housesOf(pets,'Fox');
checks['11']=!(r.length===1&&f.length===1&&!neighbors(r[0],f[0]));
const p=housesOf(hobbies,'Painting'),ho=housesOf(pets,'Horse');
checks['12']=!(p.length===1&&ho.length===1&&!neighbors(p[0],ho[0]));
const n=housesOf(nations,'Norwegian'),bl=housesOf(colors,'Blue');
checks['15']=!(n.length===1&&bl.length===1&&!neighbors(n[0],bl[0]));
console.log(Object.entries(checks).filter(([,v])=>!v));
EOF
